endpoint.example-python:
import requests

resp = requests.post("http://127.0.0.1:8612/index", json={
    "project_path": "/home/user/myproject",
    "force": False,
})
data = resp.json()
print(f"Indexed {data['files_indexed']} files, {data['files_unchanged']} unchanged, "
      f"{data['files_failed']} failed in {data['elapsed_s']:.1f}s")
if data.get("errors"):
    for err in data["errors"]:
        print(f"  ERROR {err['type']}: {err['file']} — {err['message']}")

wait-for-ready-pattern.example-python:
import time, requests

def wait_for_rag(timeout=120):
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            r = requests.get("http://127.0.0.1:8612/status", timeout=2)
            if r.status_code == 200 and r.json().get("status") == "ready":
                return True
        except requests.ConnectionError:
            pass
        time.sleep(2)
    raise TimeoutError("RAG server not ready after %ds" % timeout)

wait_for_rag()
# Now safe to call /search and /context
